use vstd::prelude::*;
use vstd::string::String;

verus! {
    // Specification of the scoring formula
    spec fn score(p: nat, t: nat) -> nat
        decreases p, t
    {
        let s1 = 3 * p / 10;
        let s2 = p - p * t / 250;
        if s1 >= s2 { s1 } else { s2 }
    }

    // Determine the winner given (P1, T1) = (a, b) and (P2, T2) = (c, d).
    // Returns exactly one of "Misha", "Vasya", or "Tie" according to the comparison
    // of the two final scores.
    fn determine_winner(a: i32, b: i32, c: i32, d: i32) -> (result: String)
        requires
            // Base points are in [250, 3500] and divisible by 250
            250 <= a && a <= 3500,
            a % 250 == 0,
            250 <= c && c <= 3500,
            c % 250 == 0,
            // Times are in [0, 180]
            0 <= b && b <= 180,
            0 <= d && d <= 180,
        ensures
            // If first score strictly larger, we return "Misha"
            (score(a as nat, b as nat) > score(c as nat, d as nat)) == (result == String::from_str("Misha")) &&
            // If second score strictly larger, we return "Vasya"
            (score(a as nat, b as nat) < score(c as nat, d as nat)) == (result == String::from_str("Vasya")) &&
            // Otherwise it's a tie
            (score(a as nat, b as nat) == score(c as nat, d as nat)) == (result == String::from_str("Tie"))
    {
        // Compute both participants' scores with Rust integer arithmetic.
        let p1: i32 = a;
        let t1: i32 = b;
        let s1_1: i32 = 3 * p1 / 10;
        let s1_2: i32 = p1 - p1 * t1 / 250;
        let s1: i32 = core::cmp::max(s1_1, s1_2);

        let p2: i32 = c;
        let t2: i32 = d;
        let s2_1: i32 = 3 * p2 / 10;
        let s2_2: i32 = p2 - p2 * t2 / 250;
        let s2: i32 = core::cmp::max(s2_1, s2_2);

        // Compare and return the appropriate string
        if s1 > s2 {
            result = String::from_str("Misha");
        } else if s2 > s1 {
            result = String::from_str("Vasya");
        } else {
            result = String::from_str("Tie");
        }
    }
}

